 * textindex — a tiny client-side full-text search library.
 *
 * Features:
 *  - Inverted index per field (term -> doc id -> term frequency)
 *  - Tokenization: lowercase; apostrophes are removed ("don't" -> "dont");
 *    every other run of non-alphanumeric characters acts as a separator
 *    ("well-known" -> "well", "known").
 *  - Stemming (see `stem()` docs for the exact rules).
 *  - tf-idf ranking with per-field boosts:
 *        score(doc, query) = sum over unique query terms t of
 *            idf(t) * sum over fields f of ( boost(f) * tf(t, doc, f) )
 *    where idf(t) = ln(N / df(t)) is computed globally across fields
 *    (df = number of distinct docs containing t in any indexed field).
 *    A term that appears in every document has idf = ln(1) = exactly 0,
 *    so ubiquitous terms contribute nothing to ranking.
 *
 * Snippet window semantics (`snippet(id, query, radius)`):
 *  - A candidate window is a set of matches whose span
 *    (last match end - first match start) is <= `radius`.
 *  - Among all candidates, the one covering the most matches wins;
 *    ties go to the earliest window.
 *  - The winning window is padded by `radius` characters on each side,
 *    clamped to the text bounds, then snapped outward to whitespace so
 *    words are never cut in half.
 *  - Returned offsets are relative to the returned snippet text.
 */

/**
 * Tokenize text: lowercase, drop apostrophes, split on any other
 * non-alphanumeric character runs.
 * @param {string} text
 * @returns {string[]}
 */
export function tokenize(text) {
  if (typeof text !== 'string') return [];
  return text
    .toLowerCase()
    .replace(/['’`]/g, '')
    .split(/[^a-z0-9]+/)
    .filter(Boolean);
}

/**
 * Tiny stemmer. Applied to each token. Rules, in order of precedence:
 *
 *  1. Gerund/participle: if the word ends in "ing" or "ed" and the
 *     remaining stem is at least 4 characters long, strip the suffix.
 *     Afterwards, if the stem ends in a doubled consonant (same letter
 *     twice), drop one copy: "running" -> "runn" -> "run",
 *     "stopped" -> "stopp" -> "stop".
 *  2. Plural: otherwise, if the word ends in "s" (but not "ss") and the
 *     remaining stem is at least 4 characters long, strip the "s":
 *     "jumps" -> "jump", "basics" -> "basic". Short stems keep the "s":
 *     "cats" stays "cats" because "cat" is only 3 characters.
 *  3. Otherwise the word is returned unchanged.
 *
 * The 4-character minimum stem prevents over-stripping short words
 * ("sing" never becomes "s", "need" keeps its "ed").
 * @param {string} word - a lowercase token
 * @returns {string}
 */
export function stem(word) {
  // Rule 1: -ing / -ed with a >= 4 char stem.
  let base = null;
  if (word.endsWith('ing')) base = word.slice(0, -3);
  else if (word.endsWith('ed')) base = word.slice(0, -2);
  if (base !== null) {
    if (base.length >= 4) {
      const last = base[base.length - 1];
      const prev = base[base.length - 2];
      if (last === prev && /[a-z0-9]/.test(last) && !/[aeiou]/.test(last)) {
        base = base.slice(0, -1);
      }
      return base;
    }
    return word; // stem too short — keep original
  }
  // Rule 2: plural -s (not -ss) with a >= 4 char stem.
  if (word.endsWith('s') && !word.endsWith('ss')) {
    const s = word.slice(0, -1);
    if (s.length >= 4) return s;
  }
  return word;
}

/**
 * Create a search index.
 * @param {object} [options]
 * @param {string[]} [options.fields=['body']] - document fields to index.
 * @param {Record<string, number>} [options.boost={}] - per-field weight
 *   multipliers used at scoring time (default 1 for unlisted fields).
 */
export function createIndex({ fields = ['body'], boost = {} } = {}) {
  if (!Array.isArray(fields) || fields.length === 0) {
    throw new Error('createIndex: fields must be a non-empty array');
  }
  /** @type {Map<string, object>} id -> original doc */
  const docs = new Map();
  /** @type {Map<string, Map<string, Map<string, number>>>} field -> term -> id -> tf */
  const postings = new Map(fields.map((f) => [f, new Map()]));
  const boosts = new Map(fields.map((f) => [f, boost[f] ?? 1]));

  function indexField(field, id, text) {
    const tf = new Map();
    for (const tok of tokenize(text)) {
      const term = stem(tok);
      tf.set(term, (tf.get(term) || 0) + 1);
    }
    const fieldIndex = postings.get(field);
    for (const [term, count] of tf) {
      let p = fieldIndex.get(term);
      if (!p) {
        p = new Map();
        fieldIndex.set(term, p);
      }
      p.set(id, count);
    }
  }

  /**
   * Add (or replace) a document. The doc must have an `id` property.
   * Missing fields are treated as empty strings.
   */
  function add(doc) {
    if (!doc || doc.id == null) throw new Error('add: document must have an id');
    if (docs.has(doc.id)) remove(doc.id); // replace = clean re-index
    docs.set(doc.id, doc);
    for (const f of fields) {
      const value = doc[f];
      indexField(f, doc.id, typeof value === 'string' ? value : '');
    }
    return doc.id;
  }

  /**
   * Remove a document and scrub every posting entry pointing at it, so a
   * removed doc can never surface in query results or snippets again.
   * @returns {boolean} true if the doc existed
   */
  function remove(id) {
    if (!docs.delete(id)) return false;
    for (const fieldIndex of postings.values()) {
      for (const [term, p] of fieldIndex) {
        if (p.delete(id) && p.size === 0) fieldIndex.delete(term);
      }
    }
    return true;
  }

  /** Global document frequency: distinct docs containing the term anywhere. */
  function df(term) {
    const ids = new Set();
    for (const fieldIndex of postings.values()) {
      const p = fieldIndex.get(term);
      if (p) for (const id of p.keys()) ids.add(id);
    }
    return ids.size;
  }

  /**
   * Query the index.
   * @param {string} text
   * @returns {{id: string, score: number}[]} sorted by score desc;
   *   ties broken by insertion order. Ubiquitous terms (in every doc)
   *   score exactly 0 and therefore don't change relative ranking.
   */
  function query(text) {
    const N = docs.size;
    if (N === 0) return [];
    const tokens = tokenize(text);
    if (tokens.length === 0) return [];

    const totals = new Map(); // id -> accumulated score
    for (const raw of new Set(tokens)) {
      const term = stem(raw);
      const contrib = new Map(); // id -> sum of boost*tf across fields
      const seen = new Set();
      for (const f of fields) {
        const p = postings.get(f).get(term);
        if (!p) continue;
        const w = boosts.get(f);
        for (const [id, tf] of p) {
          seen.add(id);
          contrib.set(id, (contrib.get(id) || 0) + w * tf);
        }
      }
      if (contrib.size === 0) continue;
      const idf = Math.log(N / df(term)); // <= 0 only when df === N → 0
      if (idf === 0) continue; // ubiquitous term contributes nothing
      for (const [id, c] of contrib) {
        totals.set(id, (totals.get(id) || 0) + c * idf);
      }
    }

    // Tie-break by insertion order of docs.
    const order = new Map([...docs.keys()].map((k, i) => [k, i]));
    return [...totals]
      .sort((a, b) => b[1] - a[1] || order.get(a[0]) - order.get(b[0]))
      .map(([id, score]) => ({ id, score }));
  }

  /**
   * Best-matching highlighted snippet for a previously added document.
   * See module docs for window semantics.
   * @param {string} id
   * @param {string} queryString
   * @param {number} [radius=40] - max match span, and padding, in characters
   * @returns {{id, field, text, offset, matches: {term,start,end}[]} | null}
   *   `offset` is the snippet's start position in the original field text;
   *   match offsets are relative to the snippet text. null if no match.
   */
  function snippet(id, queryString, radius = 40) {
    const doc = docs.get(id);
    if (!doc) return null;
    const wanted = new Set(tokenize(queryString).map(stem));
    if (wanted.size === 0) return null;

    let best = null;
    for (const field of fields) {
      const raw = doc[field];
      if (typeof raw !== 'string' || raw.length === 0) continue;
      const cand = bestWindow(raw, wanted, radius);
      if (
        cand &&
        (!best || cand.matches.length > best.matches.length)
      ) {
        best = { id, field, ...cand };
      }
    }
    return best;
  }

  return { add, remove, query, snippet, tokenize, stem };
}

/** Find the best window in raw text for a set of stemmed query terms. */
function bestWindow(raw, wantedStems, radius) {
  const hits = [];
  const re = /[A-Za-z0-9]+/g;
  let m;
  while ((m = re.exec(raw)) !== null) {
    const st = stem(m[0].toLowerCase());
    if (wantedStems.has(st)) {
      hits.push({ start: m.index, end: m.index + m[0].length, term: m[0] });
    }
  }
  if (hits.length === 0) return null;

  // Densest run of hits whose span fits within `radius`; earliest on ties.
  let bi = 0;
  let bj = 0;
  let bestCount = 0;
  for (let i = 0; i < hits.length; i++) {
    for (let j = i; j < hits.length && hits[j].end - hits[i].start <= radius; j++) {
      if (j - i + 1 > bestCount) {
        bestCount = j - i + 1;
        bi = i;
        bj = j;
      }
    }
  }

  // Pad by radius chars, clamp, then snap outward to word boundaries.
  let start = Math.max(0, hits[bi].start - radius);
  let end = Math.min(raw.length, hits[bj].end + radius);
  while (start > 0 && /\S/.test(raw[start - 1])) start--;
  while (end < raw.length && /\S/.test(raw[end])) end++;

  return {
    text: raw.slice(start, end),
    offset: start,
    matches: hits.slice(bi, bj + 1).map((h) => ({
      term: h.term,
      start: h.start - start,
      end: h.end - start,
    })),
  };
}
